let journalMonth=journalToday().slice(0,7),journalSelected=journalToday();
const journalMoods={'良い':{label:'良い',tone:'good'},'ふつう':{label:'ふつう',tone:'normal'},'ゆらぎ気味':{label:'ゆらぎ',tone:'uneasy'},'乾燥が気になる':{label:'乾燥',tone:'dry'}};
function shiftJournalMonth(delta){const [y,m]=journalMonth.split('-').map(Number),d=new Date(y,m-1+delta,1);journalMonth=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;journalSelected=journalMonth===journalToday().slice(0,7)?journalToday():journalMonth+'-01';render();}
function selectJournalDate(date){journalSelected=date;render();}
function journalGoToday(){journalSelected=journalToday();journalMonth=journalSelected.slice(0,7);render();}
function recordSelectedDate(){openJournalEntry(journalSelected);}
function careMarker(care){return ({'できた':'✓','一部できた':'◐','お休み':'−'})[care]||'';}
recordsPage=function(){
 const [year,month]=journalMonth.split('-').map(Number),first=new Date(year,month-1,1).getDay(),days=new Date(year,month,0).getDate(),today=journalToday();
 const monthRecords=state.records.filter(r=>r.date.startsWith(journalMonth)),entry=state.records.find(r=>r.date===journalSelected),mood=journalMoods[entry?.mood];
 const cells=Array.from({length:first},()=>'<span class="journal-blank" aria-hidden="true"></span>');
 for(let day=1;day<=days;day++){
  const date=`${journalMonth}-${String(day).padStart(2,'0')}`,record=state.records.find(r=>r.date===date),m=journalMoods[record?.mood],care=careMarker(record?.care);
  cells.push(`<button class="journal-day ${m?.tone||''} ${record?'recorded':''} ${date===journalSelected?'selected':''} ${date===today?'today':''}" onclick="selectJournalDate('${date}')" aria-pressed="${date===journalSelected}" aria-label="${month}月${day}日、${record?`記録あり、肌は${esc(record.mood)}、スキンケア${esc(record.care||'未記録')}`:'未記録'}" ${date>today?'disabled':''}><span class="journal-day-number">${day}</span><span class="journal-day-mood">${m?.label||(record?'記録あり':'')}</span><span class="journal-day-care" aria-hidden="true">${care||' '}</span></button>`);
 }
 return `<div class="journal-workspace calendar-workspace"><div class="workspace-heading"><div><span class="page-kicker">SKINS JOURNAL</span><h1>記録</h1></div><div class="journal-heading-actions"><button class="journal-today" onclick="journalGoToday()">今日</button><button class="journal-backup" onclick="downloadJournalBackup()" aria-label="iOSへの移行・バックアップを書き出す" title="バックアップを書き出す"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v12m-4-4 4 4 4-4M5 16v4h14v-4"/></svg></button></div></div><section class="journal-calendar" aria-label="肌とスキンケアの月カレンダー"><header class="journal-month-head"><div><strong>${year}<span>年</span> ${month}<span>月</span></strong><small>${monthRecords.length}日記録 · ケア完了 ${monthRecords.filter(r=>r.care==='できた').length}日</small></div><div><button onclick="shiftJournalMonth(-1)" aria-label="前の月">‹</button><button onclick="shiftJournalMonth(1)" aria-label="次の月" ${journalMonth>=today.slice(0,7)?'disabled':''}>›</button></div></header><div class="journal-weekdays" aria-hidden="true">${['日','月','火','水','木','金','土'].map(d=>`<span>${d}</span>`).join('')}</div><div class="journal-month-grid">${cells.join('')}</div><div class="journal-calendar-key"><span><i class="key-good"></i>良い</span><span><i class="key-normal"></i>ふつう</span><span><i class="key-uneasy"></i>ゆらぎ</span><span><i class="key-dry"></i>乾燥</span></div><p class="journal-care-key">ケア：✓ できた　◐ 一部できた　− お休み</p></section><section class="journal-selected-day" aria-labelledby="selected-date-heading"><div class="section-head"><h2 id="selected-date-heading">${Number(journalSelected.slice(5,7))}月${Number(journalSelected.slice(8))}日の記録</h2>${entry?`<span class="selected-mood ${mood?.tone||''}">${esc(entry.mood)}</span>`:'<span class="small">未記録</span>'}</div>${entry?`<dl class="journal-day-facts"><div><dt>スキンケア</dt><dd>${esc(entry.care||'未記録')}</dd></div><div><dt>睡眠</dt><dd>${esc(entry.sleep)}<small>時間</small></dd></div></dl>${entry.acneSpots?.length?`<div class="journal-acne-summary"><span>ニキビ ${entry.acneSpots.length}か所</span>${entry.acneSpots.map((s,i)=>`<div><span>${i+1} · ${esc(s.area)}</span><small class="${esc(s.status)}">${esc(acneStatuses[s.status]||'未記録')}</small></div>`).join('')}</div>`:`<p class="journal-detail-line">ニキビ：${esc(entry.acne||'なし')}</p>`}${entry.memo?`<p class="journal-day-note">${esc(entry.memo)}</p>`:''}${entry.treatment?`<p class="journal-detail-line">美容施術：${esc(entry.treatment)}</p>`:''}<button class="journal-edit-link" onclick="recordSelectedDate()">この日の記録を編集 →</button>`:'<div class="journal-date-empty"><span>'+icon('diary')+'</span><p>この日の肌とケアを記録しましょう。</p></div>'}</section><button class="journal-record-fab" onclick="recordSelectedDate()" aria-label="${Number(journalSelected.slice(5,7))}月${Number(journalSelected.slice(8))}日の${entry?'記録を編集':'記録を追加'}"><span>＋</span>記録する</button></div>`;
};

// Export locally so records can be carried from the browser into the SwiftUI app.
function downloadJournalBackup(){
 const data=new Blob([JSON.stringify({...state,schemaVersion:1},null,2)],{type:'application/json'});
 const url=URL.createObjectURL(data),link=document.createElement('a');
 link.href=url;link.download=`skins-${journalToday()}.json`;document.body.appendChild(link);link.click();link.remove();
 setTimeout(()=>URL.revokeObjectURL(url),1000);toast('バックアップを書き出しました');
}
